import { Table, TableNameColumn, StringColumn, ReferenceColumn, GuidColumn } from '@servicenow/sdk/core'

export const sys_push_notif_msg = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Push Notification Message',
    name: 'sys_push_notif_msg',
    schema: {
        table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
            },
            label: 'Table',
        }),
        name: StringColumn({
            label: 'Name',
        }),
        type: StringColumn({
            default: 'push',
            dropdown: 'dropdown_without_none',
            label: 'Type',
        }),
        push_message_content: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Select a layout that determines what the push notification looks like to users.',
                    label: 'Push Message Content',
                    plural: 'Push Message Contents',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_push_notif_msg_content',
            referenceQual: "javascript:'push_app=' + current.push_app",
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        subject: StringColumn({
            label: 'Subject',
            maxLength: 128,
        }),
        push_app: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Select the application that this message will be sent to.',
                    label: 'Push App',
                    plural: 'Push Apps',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_push_application',
            referenceQual: 'parent_appISEMPTY',
        }),
        message_string: StringColumn({
            label: [
                {
                    hint: 'Enter the push notification message. This message overrides any message that you create on the Notification form.',
                    label: 'Message',
                    plural: 'Messages',
                    language: 'en',
                },
            ],
            maxLength: 5000,
        }),
    },
    textIndex: true,
})
